import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function SellerLogin({ onClose }) {
    const navigate = useNavigate();
    const [loginData, setLoginData] = useState({
        email: '',
        password: ''
    });
    const [showPassword, setShowPassword] = useState(false);
    const [step, setStep] = useState(1); // 1: email check, 2: password entry
    const [loading, setLoading] = useState(false);
    const [sellerInfo, setSellerInfo] = useState(null);

    useEffect(() => {
        // Initialize icons if lucide is available
        if (window.lucide) {
            window.lucide.createIcons();
        }
    }, []);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setLoginData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleEmailSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.email) {
            toast.error('Please enter your email');
            return;
        }

        setLoading(true);
        
        try {
            // Check if seller exists in our database
            const response = await fetch('/api/studio/check-seller-email', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ email: loginData.email }),
            });

            const result = await response.json();

            if (response.ok) {
                if (result.exists) {
                    // Seller exists, proceed to password entry
                    setSellerInfo(result.seller);
                    setStep(2);
                } else {
                    // Seller doesn't exist in our database
                    toast.error('You are not registered as a seller for reels. Please apply first.');
                }
            } else {
                toast.error(result.message || 'An error occurred');
            }
        } catch (error) {
            console.error('Error:', error);
            toast.error('Network error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.password) {
            toast.error('Please enter your password');
            return;
        }

        setLoading(true);
        
        try {
            // Login with email and password
            const response = await fetch('/api/studio/seller-login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    email: loginData.email,
                    password: loginData.password
                }),
            });

            const result = await response.json();

            if (response.ok) {
                // Successful login
                localStorage.setItem('sellerToken', result.token);
                localStorage.setItem('sellerInfo', JSON.stringify(result.seller));
                toast.success('Login successful!');
                onClose();
                navigate('/studio/seller-dashboard');
            } else {
                toast.error(result.message || 'Invalid credentials');
            }
        } catch (error) {
            console.error('Error:', error);
            toast.error('Network error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container">
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className="card border-0 shadow-sm">
                        <div className="card-body p-4">
                            <div className="text-center mb-4">
                                <h3 className="fw-bold">Seller Login</h3>
                                <p className="text-muted">
                                    {step === 1 
                                        ? "Enter your email to verify your seller account" 
                                        : "Enter your password to login"}
                                </p>
                            </div>

                            {step === 1 ? (
                                <form onSubmit={handleEmailSubmit}>
                                    <div className="mb-3">
                                        <label className="form-label">Email Address</label>
                                        <input
                                            type="email"
                                            className="form-control form-control-lg"
                                            name="email"
                                            value={loginData.email}
                                            onChange={handleInputChange}
                                            placeholder="Enter your email"
                                            required
                                        />
                                    </div>
                                    
                                    <div className="d-grid gap-2">
                                        <button
                                            type="submit"
                                            className="btn btn-primary btn-lg"
                                            disabled={loading}
                                        >
                                            {loading ? (
                                                <span>
                                                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                    Verifying...
                                                </span>
                                            ) : (
                                                'Verify Email'
                                            )}
                                        </button>
                                    </div>
                                    
                                    <div className="text-center mt-3">
                                        <p className="mb-0">
                                            Don't have an account?{' '}
                                            <button
                                                type="button"
                                                className="btn btn-link p-0 m-0 text-decoration-underline"
                                                onClick={() => navigate('/studio/apply-for-reels')}
                                            >
                                                Apply for Reels
                                            </button>
                                        </p>
                                    </div>
                                </form>
                            ) : (
                                <form onSubmit={handlePasswordSubmit}>
                                    <div className="mb-3">
                                        <label className="form-label">Email</label>
                                        <input
                                            type="email"
                                            className="form-control form-control-lg"
                                            value={loginData.email}
                                            readOnly
                                        />
                                    </div>
                                    
                                    <div className="mb-3">
                                        <label className="form-label">Password</label>
                                        <div className="input-group">
                                            <input
                                                type={showPassword ? "text" : "password"}
                                                className="form-control form-control-lg"
                                                name="password"
                                                value={loginData.password}
                                                onChange={handleInputChange}
                                                placeholder="Enter your password"
                                                required
                                            />
                                            <button
                                                className="btn btn-outline-secondary"
                                                type="button"
                                                onClick={() => setShowPassword(!showPassword)}
                                            >
                                                {showPassword ? (
                                                    <i data-lucide="eye-off"></i>
                                                ) : (
                                                    <i data-lucide="eye"></i>
                                                )}
                                            </button>
                                        </div>
                                    </div>
                                    
                                    <div className="d-grid gap-2">
                                        <button
                                            type="submit"
                                            className="btn btn-primary btn-lg"
                                            disabled={loading}
                                        >
                                            {loading ? (
                                                <span>
                                                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                    Logging in...
                                                </span>
                                            ) : (
                                                'Login'
                                            )}
                                        </button>
                                    </div>
                                    
                                    <div className="text-center mt-3">
                                        <button
                                            type="button"
                                            className="btn btn-link p-0 m-0 text-decoration-underline"
                                            onClick={() => setStep(1)}
                                        >
                                            Change Email
                                        </button>
                                    </div>
                                </form>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
